def trig3():
    w,h=520,640
    s=''
    def panel(y0,H,fn,title,ymax,ytop,ybot,asym=False):
        mid=y0+H/2
        X=lambda d:40+d/360*420
        Y=lambda v:mid-v/ymax*(H/2-10)
        o=f'<path d="M40 {mid}H500M40 {y0}V{y0+H}" stroke="#334155" stroke-width="1.5" fill="none"/>'
        for d in (90,180,270,360):o+=f'<path d="M{X(d):.1f} {mid-4}v8" stroke="#334155"/>'+tx(X(d)-10,mid+16,f'{d}°',11)
        o+=tx(220,y0+14,title,14)+tx(8,Y(ymax*0.95)+4,ytop,11)+tx(4,Y(-ymax*0.95)+4,ybot,11)
        if asym:
            for a0,a1 in ((0,90),(90,270),(270,360)):
                seg=[]
                for i in range(61):
                    d=a0+(a1-a0)*i/60
                    if abs(d-90)<2 or abs(d-270)<2:continue
                    v=fn(d)
                    if abs(v)<=ymax:seg.append(f'{"M" if not seg else "L"}{X(d):.1f} {Y(v):.1f}')
                o+=f'<path d="{" ".join(seg)}" fill="none" stroke="#2563eb" stroke-width="2.4"/>'
            o+=f'<path d="M{X(90):.1f} {y0+8}V{y0+H-8}M{X(270):.1f} {y0+8}V{y0+H-8}" stroke="#94a3b8" stroke-dasharray="4 4"/>'
        else:
            seg=[f'{"M" if i==0 else "L"}{X(360*i/90):.1f} {Y(fn(360*i/90)):.1f}' for i in range(91)]
            o+=f'<path d="{" ".join(seg)}" fill="none" stroke="#2563eb" stroke-width="2.4"/>'
        return o
    s+=panel(10,170,lambda d:math.sin(math.radians(d)),'y = sin x',1.15,'1','-1')
    s+=panel(220,170,lambda d:math.cos(math.radians(d)),'y = cos x',1.15,'1','-1')
    s+=panel(430,190,lambda d:math.tan(math.radians(d)),'y = tan x',4.5,'10','-10',True)
    return S(w,h,'Figure 12.13: the graphs of y = sin x, y = cos x and y = tan x for 0 to 360 degrees',s)
